macro_rules! deps {
    () => {
        CycleHead!();
    };
}

macro_rules! CycleHeads {
    () => {
        deps!();
        # [doc = " Any provisional value generated by any query in a cycle will track the cycle head(s) (can be"] # [doc = " plural in case of nested cycles) representing the cycles it is part of, and the current"] # [doc = " iteration count for each cycle head. This struct tracks these cycle heads."] # [derive (Clone , Debug , Default)] pub struct CycleHeads (ThinVec < CycleHead >) ;
    };
}

CycleHeads!()